import arBase from "@/i18n/ar.json";
import ccAr from "@/i18n/control-center/ar.json";
import ccEn from "@/i18n/control-center/en.json";
import ccFr from "@/i18n/control-center/fr.json";
import enBase from "@/i18n/en.json";
import frBase from "@/i18n/fr.json";
import type { Dictionary, Locale } from "./i18n-core";

/**
 * Shared product strings (generated by scripts/gen-i18n.py) merged with Control Center specific strings
 * (src/i18n/control-center/*.json, hand-maintained).
 */
export const DICTIONARIES: Record<Locale, Dictionary> = {
  en: { ...enBase, ...ccEn },
  fr: { ...frBase, ...ccFr },
  ar: { ...arBase, ...ccAr },
};

export function getDictionary(locale: Locale): Dictionary {
  return DICTIONARIES[locale];
}
